#[derive(Debug, thiserror::Error)]
pub enum LibraryError {
    #[error("读写角色库失败: {0}")]
    Io(#[from] std::io::Error),
    #[error("解析角色配置失败: {0}")]
    Json(#[from] serde_json::Error),
    #[error("打包/解包失败: {0}")]
    Zip(#[from] zip::result::ZipError),
    #[error("音频处理失败: {0}")]
    Audio(String),
    #[error("{0}")]
    Invalid(String),
}

type Result<T> = std::result::Result<T, LibraryError>;

/// 当前 Unix 毫秒时间戳
pub fn now_millis() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_millis() as i64)
        .unwrap_or_default()
}

/// 角色库
#[derive(Debug, Clone)]
pub struct Library {
    root: PathBuf,
}

impl Library {
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    fn character_dir(&self, id: &str) -> PathBuf {
        self.root.join(id)
    }

    /// 角色库根目录 (仅测试使用)
    #[cfg(test)]
    pub fn root(&self) -> &Path {
        &self.root
    }

    fn character_file(&self, id: &str) -> PathBuf {
        self.root.join(format!("{id}.json"))
    }

    /// 列出全部角色 (完整配置)
    ///
    /// 排序**只看星标与创建时间**, 不看更新时间: 后者会让"改一下某个角色的设置"
    /// 把它的卡片挪到列表最前面, 用户会以为卡片之间交换了位置。
    pub fn list(&self) -> Result<Vec<Character>> {
        let mut characters = Vec::new();
        if !self.root.is_dir() {
            return Ok(characters);
        }
        for entry in std::fs::read_dir(&self.root)? {
            let entry = entry?;
            let path = entry.path();
            if path.extension().and_then(|ext| ext.to_str()) != Some("json")
                || path.ends_with("index.json")
            {
                continue;
            }
            match std::fs::read_to_string(&path)
                .map_err(LibraryError::from)
                .and_then(|text| {
                    serde_json::from_str::<Character>(&text).map_err(LibraryError::from)
                }) {
                Ok(character) => characters.push(character),
                Err(error) => eprintln!("跳过无法解析的角色配置 {}: {error}", path.display()),
            }
        }
        characters.sort_by(|a, b| {
            b.starred
                .cmp(&a.starred)
                .then(a.created_at.cmp(&b.created_at))
                .then(a.name.cmp(&b.name))
        });
        Ok(characters)
    }

    /// 读取单个角色
    pub fn load(&self, id: &str) -> Result<Character> {
        let path = self.character_file(id);
        if !path.is_file() {
            return Err(LibraryError::Invalid(format!("角色 {id} 不存在")));
        }
        let text = std::fs::read_to_string(path)?;
        Ok(serde_json::from_str(&text)?)
    }

    /// 按**字段**修改角色: 只改动给出的字段, 其余以磁盘上的当前内容为准。
    ///
    /// 这是角色修改的唯一入口。原因: 前端曾经把**整份角色记录**发回来写盘, 于是
    /// 两个并发/相邻的修改会互相覆盖 —— 勾选"参与配音"会顺手把星标、模型等字段
    /// 回写成它手上那份可能已经过时的快照。改成"服务端读-改-写"之后, 每个操作
    /// 只影响它声明要改的字段。
    pub fn patch(&self, id: &str, patch: CharacterPatch) -> Result<Character> {
        let mut character = self.load(id)?;
        if let Some(name) = patch.name {
            let name = name.trim().to_string();
            if name.is_empty() {
                return Err(LibraryError::Invalid("角色名不可为空".into()));
            }
            character.name = name;
        }
        if let Some(description) = patch.description {
            character.description = description;
        }
        if let Some(language) = patch.language {
            character.language = language;
        }
        if let Some(model) = patch.model {
            character.model = model;
        }
        if let Some(starred) = patch.starred {
            character.starred = starred;
        }
        if let Some(enabled) = patch.enabled {
            character.enabled = enabled;
        }
        self.save(character)
    }

    /// 写入单个角色 (更新时间戳)
    pub fn save(&self, mut character: Character) -> Result<Character> {
        if character.id.trim().is_empty() {
            return Err(LibraryError::Invalid("角色 id 不可为空".into()));
        }
        std::fs::create_dir_all(&self.root)?;
        character.updated_at = now_millis();
        let text = serde_json::to_string_pretty(&character)?;
        std::fs::write(self.character_file(&character.id), text)?;
        Ok(character)
    }

    /// 写入单个角色, 并处理**改名** (id 变化)。
    ///
    /// id 同时是配置文件名与参考音频目录名 (也是导出到 `game/vocal/<id>/` 的目录名),
    /// 因此改名必须连带搬移参考音频目录并清掉旧配置 —— 否则会留下一个"幽灵角色",
    /// 或者新角色指向不存在的音频。
    pub fn save_as(&self, previous_id: Option<&str>, character: Character) -> Result<Character> {
        let previous = previous_id
            .map(str::trim)
            .filter(|id| !id.is_empty() && *id != character.id);
        if let Some(previous) = previous {
            if self.character_file(&character.id).is_file() {
                return Err(LibraryError::Invalid(format!(
                    "角色 id {} 已被占用",
                    character.id
                )));
            }
            let from = self.character_dir(previous);
            if from.is_dir() {
                let to = self.character_dir(&character.id);
                if to.is_dir() {
                    std::fs::remove_dir_all(&to)?;
                }
                std::fs::rename(&from, &to)?;
            }
            let old_file = self.character_file(previous);
            if old_file.is_file() {
                std::fs::remove_file(old_file)?;
            }
        }
        self.save(character)
    }

    /// 删除角色及其参考音频目录
    pub fn remove(&self, id: &str) -> Result<()> {
        let file = self.character_file(id);
        if file.is_file() {
            std::fs::remove_file(file)?;
        }
        let dir = self.character_dir(id);
        if dir.is_dir() {
            std::fs::remove_dir_all(dir)?;
        }
        Ok(())
    }

    /// 参考音频的绝对路径
    pub fn reference_path(&self, id: &str, file: &str) -> PathBuf {
        self.character_dir(id).join(file)
    }

    /// 从 GPT-SoVITS 的切片产物导入角色与参考音频。
    ///
    /// 输入是一份 `.list` 文本清单与一个音频目录 (两者位置无关, 由用户分别指定):
    /// * `list_path` - 清单文件, 每行形如
    ///   `音频相对路径|说话者|语言|文本` (路径形如 `output\slicer_opt\<角色>\<文件>.wav`);
    /// * `audio_dir` - 已切好的音频, 可任意层级嵌套。
    ///
    /// 匹配方式是**按文件名**: 先深度遍历音频目录建立 "文件名(小写) -> 路径" 索引,
    /// 再用清单里那条路径的文件名去查。这样清单里写的是哪台机器的路径都无所谓。
    ///
    /// 导入规则:
    /// * 说话者即角色名 (不存在则新建角色); 清单没有说话者时退回清单文件名;
    /// * 语言取 `.list` 中的标识 (如 `JA` -> `ja`), 无法识别时退回 `auto`;
    /// * 每段音频都按参考音频约束规范化 (过短补静音、过长按静音边界裁剪);
    /// * **没有条数上限**。曾经有过一个上限 (先是 48, 后是 5000), 结果是"导入 109 条"
    ///   被静默截断, 用户只看到"跳过 61 条"却不知道那是上限。真实语料每个角色上百条
    ///   很常见, 是否需要谨慎由用户在导入前判断 (见 [`Library::preview_from_list`]),
    ///   而不是由这里替他丢数据。
    pub fn import_from_list(
        &self,
        list_path: &Path,
        audio_dir: &Path,
    ) -> Result<ListImportReport> {
        let (by_speaker, malformed) = self.read_list_by_speaker(list_path, audio_dir)?;

        let mut report = ListImportReport {
            skipped: malformed,
            ..Default::default()
        };
        let staging_root = self.root.join(".import-staging");
        std::fs::create_dir_all(&staging_root)?;

        // 音频索引: 文件名 (小写) -> 绝对路径, 供清单里的相对路径反查
        let audio_index = index_audio_files(audio_dir);

        for (speaker, records) in by_speaker {
            let existing = self.find_by_name(&speaker)?;
            let mut character = match existing {
                Some(character) => character,
                None => {
                    let root = &self.root;
                    std::fs::create_dir_all(root)?;
                    let now = now_millis();
                    Character {
                        id: unique_id(root, &speaker),
                        name: speaker.clone(),
                        // 描述刻意留空: 它是给"AI 融入编辑流程"用的角色说明,
                        // 自动写一句"由某路径导入"只会污染这份信息。
                        description: String::new(),
                        language: "auto".into(),
                        references: Vec::new(),
                        model: None,
                        starred: false,
                        enabled: true,
                        created_at: now,
                        updated_at: now,
                    }
                }
            };

            let dir = self.character_dir(&character.id);
            std::fs::create_dir_all(&dir)?;
            let staged = staging_root.join("staged.wav");

            let mut kept: std::collections::HashSet<String> = character
                .references
                .iter()
                .map(|reference| reference.hash.clone())
                .collect();

            for record in records {
                let Some(audio_path) = lookup_audio(&audio_index, &record.audio) else {
                    report.skipped += 1;
                    continue;
                };
                // 规范化: 过短的补尾静音, 过长的按静音边界**自动裁剪**, 超出部分夹到上限。
                // 不因为"太长"而丢数据 —— 单条添加走同一套自动裁剪, 失败才由界面弹手动裁剪。
                let Ok(normalized) = super::audio::normalize_reference(&audio_path, &staged, None)
                else {
                    report.skipped += 1;
                    continue;
                };
                if normalized.trimmed {
                    report.auto_trimmed += 1;
                }
                if !kept.insert(normalized.hash.clone()) {
                    report.skipped += 1;
                    continue;
                }
                let reference = self.adopt_reference(
                    &character.id,
                    &staged,
                    record.text,
                    normalize_language(&record.language),
                    vec!["导入".to_string()],
                )?;
                character.references.push(reference);
                report.imported += 1;
            }

            let _ = std::fs::remove_file(&staged);
            if !character.references.is_empty() {
                report.characters.push(character.name.clone());
                self.save(character)?;
            }
        }

        let _ = std::fs::remove_dir_all(&staging_root);
        report.characters.sort();
        report.characters.dedup();
        Ok(report)
    }

    /// 读取清单并按说话者聚合。
    ///
    /// 导入与预览共用这一份解析: 两边各自实现一次的话, "预览说 320 条、实际导入 280 条"
    /// 这类不一致迟早会出现, 而用户正是拿这个数字决定要不要继续。
    ///
    /// 返回值第二项是无法解析的行数 (会被计入 `skipped`)。
    fn read_list_by_speaker(
        &self,
        list_path: &Path,
        audio_dir: &Path,
    ) -> Result<(std::collections::BTreeMap<String, Vec<ListRecord>>, usize)> {
        if !list_path.is_file() {
            return Err(LibraryError::Invalid(format!(
                "清单文件不存在: {}",
                list_path.display()
            )));
        }
        if !audio_dir.is_dir() {
            return Err(LibraryError::Invalid(format!(
                "音频目录不存在: {}",
                audio_dir.display()
            )));
        }

        let text = std::fs::read_to_string(list_path)?;
        // 角色优先取清单内的说话者; 无说话者时退回清单文件名
        let file_stem = list_path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .unwrap_or("character")
            .to_string();

        let mut by_speaker: std::collections::BTreeMap<String, Vec<ListRecord>> =
            std::collections::BTreeMap::new();
        let mut malformed = 0usize;
        for line in text.lines() {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            match parse_list_line(line) {
                Some(record) => {
                    let speaker = if record.speaker.trim().is_empty() {
                        file_stem.clone()
                    } else {
                        record.speaker.trim().to_string()
                    };
                    by_speaker.entry(speaker).or_default().push(record);
                }
                None => malformed += 1,
            }
        }
        Ok((by_speaker, malformed))
    }

    /// 预览一次 `.list` 导入: 有多少条、涉及哪些角色、各多少条。
    ///
    /// 供界面在**真正导入前**决定要不要提醒用户 (条数很多时导入很慢, 而且每段音频都会
    /// 被拷贝进角色库)。条数与角色直接来自清单解析, 与导入完全同一套规则;
    /// `matched` 只判断"音频目录里能不能按文件名找到", 不做解码与规范化
    /// (那才是导入慢的原因), 因此它可能在个别文件损坏时略高于实际导入数。
    pub fn preview_from_list(
        &self,
        list_path: &Path,
        audio_dir: &Path,
    ) -> Result<ListImportPreview> {
        // 无法解析的行不进预览: 界面上的数字要能一一对应到"将会导入什么"
        let (by_speaker, _malformed) = self.read_list_by_speaker(list_path, audio_dir)?;
        let audio_index = index_audio_files(audio_dir);

        let mut characters = Vec::new();
        let mut records = 0usize;
        let mut matched = 0usize;
        for (name, items) in by_speaker {
            records += items.len();
            let hits = items
                .iter()
                .filter(|record| lookup_audio(&audio_index, &record.audio).is_some())
                .count();
            matched += hits;
            characters.push(ListImportCharacter {
                name,
                count: hits,
            });
        }
        // 条数多的排前面: 用户要判断的正是"有没有哪个角色特别多"
        characters.sort_by(|a, b| b.count.cmp(&a.count).then(a.name.cmp(&b.name)));

        Ok(ListImportPreview {
            records,
            matched,
            characters,
        })
    }

    /// 按名称查找角色 (大小写与首尾空白不敏感)
    fn find_by_name(&self, name: &str) -> Result<Option<Character>> {
        let needle = name.trim().to_lowercase();
        for character in self.list()? {
            if character.name.trim().to_lowercase() == needle {
                return Ok(Some(character));
            }
        }
        Ok(None)
    }

    /// 把一份已经规范化好的参考音频纳入角色库 (内容寻址, 同内容自动复用)
    pub fn adopt_reference(
        &self,
        id: &str,
        source: &Path,
        text: String,
        language: LanguageCode,
        tags: Vec<StyleTag>,
    ) -> Result<ReferenceAudio> {
        let dir = self.character_dir(id);
        std::fs::create_dir_all(&dir)?;

        let hash = super::audio::hash_file(source).map_err(LibraryError::Audio)?;
        let file_name = format!("ref_{hash}.wav");
        let target = dir.join(&file_name);
        if !target.is_file() {
            std::fs::copy(source, &target)?;
        }

        let probe = super::audio::probe(&target).map_err(LibraryError::Audio)?;
        Ok(ReferenceAudio {
            file: file_name,
            hash,
            duration: probe.duration,
            sample_rate: probe.sample_rate,
            text,
            language,
            tags,
            created_at: now_millis(),
        })
    }

    /// 删除参考音频文件 (若库内已无其他条目引用同一文件)
    pub fn drop_reference_file(&self, id: &str, file: &str, still_used: bool) -> Result<()> {
        if still_used {
            return Ok(());
        }
        let path = self.reference_path(id, file);
        if path.is_file() {
            std::fs::remove_file(path)?;
        }
        Ok(())
    }

    /// 导出角色为 zip 压缩包 (清单 + 参考音频, 不含模型选择)
    pub fn export_zip(&self, id: &str, destination: &Path) -> Result<()> {
        use std::io::Write;
        use zip::write::SimpleFileOptions;

        let character = self.load(id)?;
        let manifest = CharacterManifest {
            version: 1,
            name: character.name.clone(),
            description: character.description.clone(),
            language: character.language.clone(),
            references: character.references.clone(),
        };

        if let Some(parent) = destination.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let file = std::fs::File::create(destination)?;
        let mut writer = zip::ZipWriter::new(file);
        let options =
            SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated);

        writer.start_file("character.json", options)?;
        writer.write_all(serde_json::to_string_pretty(&manifest)?.as_bytes())?;

        for reference in &character.references {
            let path = self.reference_path(id, &reference.file);
            if !path.is_file() {
                continue;
            }
            let bytes = std::fs::read(&path)?;
            writer.start_file(format!("audio/{}", reference.file), options)?;
            writer.write_all(&bytes)?;
        }
        writer.finish()?;
        Ok(())
    }

    /// 从 zip 压缩包导入角色, 返回导入后的角色
    pub fn import_zip(&self, source: &Path) -> Result<Character> {
        use std::io::Read;

        let file = std::fs::File::open(source)?;
        let mut archive = zip::ZipArchive::new(file)?;

        let manifest: CharacterManifest = {
            let mut entry = archive
                .by_name("character.json")
                .map_err(|_| LibraryError::Invalid("压缩包内缺少 character.json".into()))?;
            let mut text = String::new();
            entry.read_to_string(&mut text)?;
            serde_json::from_str(&text)?
        };

        let id = unique_id(&self.root, &manifest.name);
        let dir = self.character_dir(&id);
        std::fs::create_dir_all(&dir)?;

        let mut references = Vec::new();
        for reference in manifest.references {
            let zip_name = format!("audio/{}", reference.file);
            let mut entry = match archive.by_name(&zip_name) {
                Ok(entry) => entry,
                Err(_) => continue,
            };
            let mut bytes = Vec::new();
            entry.read_to_end(&mut bytes)?;

            // 以实际内容重新计算哈希, 防止清单被篡改或文件名与内容不符
            let target = dir.join(&reference.file);
            std::fs::write(&target, &bytes)?;
            let hash = super::audio::hash_file(&target).map_err(LibraryError::Audio)?;
            let probe = super::audio::probe(&target).map_err(LibraryError::Audio)?;
            if probe.too_short || probe.too_long {
                // 导入的参考音频不满足 GSOV 时长约束时直接拒绝, 避免生成阶段才报错
                let _ = std::fs::remove_file(&target);
                return Err(LibraryError::Invalid(format!(
                    "参考音频 {} 时长为 {:.2}s, 不在 3~10s 范围内",
                    reference.file, probe.duration
                )));
            }
            references.push(ReferenceAudio {
                file: format!("ref_{hash}.wav"),
                hash,
                duration: probe.duration,
                sample_rate: probe.sample_rate,
                ..reference
            });
        }

        let now = now_millis();
        let character = Character {
            id,
            name: manifest.name,
            description: manifest.description,
            language: manifest.language,
            references,
            model: None,
            starred: false,
            enabled: true,
            created_at: now,
            updated_at: now,
        };
        self.save(character)
    }
}

/// 依据角色名生成库内唯一 id
pub fn unique_id(root: &Path, name: &str) -> String {
    let base = slugify(name);
    let base = if base.is_empty() {
        "character".to_string()
    } else {
        base
    };
    if !root.join(format!("{base}.json")).exists() {
        return base;
    }
    for suffix in 2..1000 {
        let candidate = format!("{base}-{suffix}");
        if !root.join(format!("{candidate}.json")).exists() {
            return candidate;
        }
    }
    format!("{base}-{}", now_millis())
}

/// 把 `-vocal=` 的值解析为项目内音频文件的绝对路径。
///
/// WebGAL 的取值是**相对 `game/vocal/` 的路径** (例如 `anon/a1b2c3d4.wav`),
/// 引擎侧对应 `./game/vocal/${value}`, 因此这里只需拼接即可。
/// 值里可能使用 `/` 或 `\`, 统一归一化后再拼接。
pub fn resolve_audio_path(project: &Path, vocal: &str) -> PathBuf {
    let normalized = vocal.replace('\\', "/");
    let mut path = project.join("game").join("vocal");
    for segment in normalized.split('/') {
        // 跳过空段与 `.`, 拒绝 `..` 以防越界
        if segment.is_empty() || segment == "." {
            continue;
        }
        if segment == ".." {
            continue;
        }
        path.push(segment);
    }
    path
}

/// 生成可用作文件名/id 的 slug。
///
/// **只保留 ASCII 字母与数字**: 角色 id 会成为磁盘上的目录名 (`game/vocal/<id>/`) 与
/// 配置文件名, 中文 id 在跨工具、跨平台时很容易出问题, 而且用户想手改也不好输入。
/// 中文名会被折叠成空, 由 [`unique_id`] 退回 `character` / `character-<时间戳>`。
/// 角色名本身不受影响 —— 界面上显示与解析用的始终是名字。
pub fn slugify(name: &str) -> String {
    let mut out = String::new();
    let mut last_dash = false;
    for ch in name.trim().chars() {
        if ch.is_ascii_alphanumeric() {
            out.push(ch.to_ascii_lowercase());
            last_dash = false;
        } else if !last_dash && !out.is_empty() {
            out.push('-');
            last_dash = true;
        }
    }
    out.trim_matches('-').to_string()
}

